.darma-loader-darma-b14-iv-drip { --accent: var(--loader-color, #0ea5e9); --accent-2: var(--loader-secondary-color, #94a3b8); width: calc(var(--loader-size, 116px) * .6); height: var(--loader-size, 116px); position: relative; }
.darma-loader-darma-b14-iv-drip::before { content: ''; position: absolute; top: 44%; left: 47%; width: 5%; height: 56%; border-radius: 2px; background: color-mix(in srgb, #fff 46%, var(--accent-2)); }
.darma-loader-darma-b14-iv-drip .darma-loader-darma-b14-iv-drip__bag { position: absolute; top: 0; left: 13%; width: 74%; height: 44%; overflow: hidden; border-radius: 6px 6px 42% 42%; background: color-mix(in srgb, #fff 60%, var(--accent-2)); box-shadow: inset 0 0 0 2px color-mix(in srgb, #000 16%, var(--accent-2)); }
.darma-loader-darma-b14-iv-drip .darma-loader-darma-b14-iv-drip__bag::after { content: ''; position: absolute; bottom: 0; left: 0; width: 100%; background: linear-gradient(color-mix(in srgb, #fff 22%, var(--accent)), var(--accent)); animation: darma-loader-darma-b14-iv-drip-drain calc(var(--loader-speed, 1s) * 4) linear infinite; }
.darma-loader-darma-b14-iv-drip span { position: absolute; top: 48%; left: 46%; width: 7%; height: 9%; border-radius: 50% 50% 62% 62%; background: var(--accent); animation: darma-loader-darma-b14-iv-drip-drop-fall calc(var(--loader-speed, 1s) * 1.4) ease-in infinite; }
.darma-loader-darma-b14-iv-drip span:nth-child(3) { animation-delay: calc(var(--loader-speed, 1s) * .7); }
@keyframes darma-loader-darma-b14-iv-drip-drain { 0% { height: 88%; } 100% { height: 22%; } }
@keyframes darma-loader-darma-b14-iv-drip-drop-fall { 0% { opacity: 0; transform: translateY(0) scaleY(.6); } 16% { opacity: 1; } 72% { transform: translateY(200%) scaleY(1.1); } 100% { opacity: 0; transform: translateY(250%) scaleY(.5); } }

